// ---------------------------------------------------------------------------
// Two-layer safety filter (per design doc D4).
//
// Layer 1 is in the system prompt above (rules 1, 2, 3). Layer 2 is this
// post-generation regex pass. Phrases are matched case-insensitively. On
// any match we replace the entire response with SAFE_FALLBACK and log the
// violation server-side.
//
// The forbidden phrase lists are conservative. False positives are OK
// (SAFE_FALLBACK is still a useful, non-refusing response). False negatives
// kill the demo.
// ---------------------------------------------------------------------------

const FORBIDDEN_PHRASES_EN: RegExp[] = [
  /\byou\s+(do\s+)?qualify\b/i,
  /\byou\s+(do\s+)?(not|don'?t)\s+qualify\b/i,
  /\byou\s+(are|'re)\s+eligible\b/i,
  /\byou\s+(are|'re)\s+not\s+eligible\b/i,
  /\byou\s+(are|'re)\s+ineligible\b/i,
  /\byou\s+should\s+report\b/i,
  /\byou\s+(must|need\s+to)\s+report\b/i,
  /\byou\s+should\s+(select|choose|pick|answer|say)\b/i,
  /\byou\s+(must|need\s+to)\s+(select|choose|pick|answer|say)\b/i,
  /\byou\s+will\s+(be\s+)?(approved|denied)\b/i,
  /\byou\s+(will\s+)?get\s+(approved|denied)\b/i,
  /\bbenefits?\s+will\s+be\s+(approved|denied)\b/i,
];

const FORBIDDEN_PHRASES_ES: RegExp[] = [
  /\busted\s+califica\b/i,
  /\busted\s+no\s+califica\b/i,
  /\busted\s+es\s+elegible\b/i,
  /\busted\s+no\s+es\s+elegible\b/i,
  /\busted\s+debe\s+reportar\b/i,
  /\busted\s+tiene\s+que\s+reportar\b/i,
  /\busted\s+debe\s+(seleccionar|elegir|responder|decir)\b/i,
  /\busted\s+tiene\s+que\s+(seleccionar|elegir|responder|decir)\b/i,
  /\busted\s+ser[aá]\s+(aprobado|negado|denegado)\b/i,
  /\bsus\s+beneficios?\s+ser[aá]n?\s+(aprobado|negado|denegado)s?\b/i,
];

const SAFE_FALLBACK_EN =
  "This question is asking for specific information about your situation. We don't want to guess and give you the wrong answer, so your county navigator can walk you through it. You can also call 2-1-1 for free help filling out the application.";

const SAFE_FALLBACK_ES =
  "Esta pregunta pide información específica sobre su situación. No queremos adivinar y darle la respuesta incorrecta, así que un orientador del condado puede guiarlo. También puede llamar al 2-1-1 para obtener ayuda gratuita para completar la solicitud.";

/**
 * Apply the post-generation safety filter. Returns the cleaned text and
 * whether a forbidden phrase was matched. On match, the original response
 * and matched pattern are logged server-side for post-demo review.
 */
function applySafetyFilter(
  rawText: string,
  locale: "en" | "es",
  context: { question_title: string; anonymous_id: string | null },
): { text: string; was_filtered: boolean } {
  const phrases = locale === "es" ? FORBIDDEN_PHRASES_ES : FORBIDDEN_PHRASES_EN;
  for (const pattern of phrases) {
    if (pattern.test(rawText)) {
      // Structured violation event — greppable in server logs.
      // We log the original response + matched pattern so an operator can
      // tighten the system prompt post-demo without losing the trigger.
      console.log(
        JSON.stringify({
          level: "warn",
          msg: "intake_help_safety_filter_triggered",
          route: "POST /v1/intake/help",
          locale,
          matched_pattern: pattern.source,
          question_title: context.question_title.slice(0, 200),
          anonymous_id: context.anonymous_id,
          original_response: rawText.slice(0, 1000),
          ts: new Date().toISOString(),
        }),
      );
      return {
        text: locale === "es" ? SAFE_FALLBACK_ES : SAFE_FALLBACK_EN,
        was_filtered: true,
      };
    }
  }
  return { text: rawText, was_filtered: false };
}

// ---------------------------------------------------------------------------
// Anonymous-id bucket middleware.
//
// Synthesizes a per-request actor row keyed by the x-anonymous-id header so
// the shared rateLimit("strict") middleware keys its bucket per anonymous
// caller rather than collapsing every anonymous caller into a shared IP
// bucket. The actor `kind` is "applicant" — closest match in the existing
// ActorKind union — but the route never reads it back.
// ---------------------------------------------------------------------------

async function requireAnonymousId(c: Context<{ Bindings: Env }>, next: Next): Promise<void> {
  const anonymousId = c.req.header("x-anonymous-id")?.trim();
  if (!anonymousId) {
    throw new HTTPException(400, { message: "Missing x-anonymous-id header" });
  }
  // Stash a synthetic actor so rateLimit("strict") keys per-anonymous-id.
  const synthetic: Actor = { kind: "applicant", id: `anon:${anonymousId}` };
  c.set("actor", synthetic);
  await next();
}

// ---------------------------------------------------------------------------
// Anthropic invocation (native fetch, no npm SDK).
//
// The Workers runtime doesn't support Deno-style npm: imports, and adding
// @anthropic-ai/sdk to package.json bloats the cold start for one call.
// We use the same native-fetch pattern as packages/recert-engine/src/
// interview/scorer.ts so this stays consistent with the rest of the codebase.
// ---------------------------------------------------------------------------

type AnthropicContentBlock =
  | { type: "text"; text: string }
  | { type: "tool_use"; id: string; name: string; input: unknown };

type AnthropicResponse = {
  content?: AnthropicContentBlock[];
};

export type FetchImpl = typeof fetch;

/**
 * Builds the user message. When `questionHelper` is present, the model is
 * told to ground its explanation in Civica's own on-screen helper copy for
 * that exact question — expand and clarify it, never contradict it.
 */
function buildUserMessage(questionTitle: string, questionHelper?: string): string {
  const base = `The applicant tapped the help button next to this question:\n\n"${questionTitle}"`;
  const trimmed = questionHelper?.trim();
  const helperBlock =
    trimmed && trimmed.length > 0
      ? `\n\nCivica already shows the applicant this helper text for this question:\n"${trimmed}"\n\nGround your explanation in that helper — expand and clarify it in plain language. Do not contradict it.`
      : "";
  return `${base}${helperBlock}\n\nExplain what this question is asking in 2-5 short sentences.`;
}

async function callAnthropic(
  apiKey: string,
  systemPrompt: string,
  questionTitle: string,
  questionHelper: string | undefined,
  fetchImpl: FetchImpl = fetch,
): Promise<string> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const response = await fetchImpl("https://api.anthropic.com/v1/messages", {
      method: "POST",
      signal: controller.signal,
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: MODEL,
        max_tokens: MAX_TOKENS,
        temperature: 0.3,
        system: systemPrompt,
        messages: [
          {
            role: "user",
            content: buildUserMessage(questionTitle, questionHelper),
          },
        ],
      }),
    });

    if (!response.ok) {
      const body = await response.text().catch(() => "");
      throw new Error(`Anthropic API error ${response.status}: ${body.slice(0, 500)}`);
    }

    const data = (await response.json()) as AnthropicResponse;
    const textBlock = data.content?.find(
      (b): b is Extract<AnthropicContentBlock, { type: "text" }> => b.type === "text",
    );
    if (!textBlock || typeof textBlock.text !== "string" || textBlock.text.trim().length === 0) {
      throw new Error("Anthropic response missing text content");
    }
    return textBlock.text.trim();
  } finally {
    clearTimeout(timeout);
  }
}

// Test-only seam: lets the vitest suite swap in a mock fetch without
// monkey-patching globalThis. Production callers go through the default fetch.
let _fetchOverride: FetchImpl | null = null;
export function __setFetchForTests(impl: FetchImpl | null): void {
  _fetchOverride = impl;
}

// ---------------------------------------------------------------------------
// Response caching via the Workers Cache API (caches.default).
//
// No KV namespace, no wrangler.toml binding — the Cache API is the idiomatic
// Workers primitive for HTTP response caching. We key on a SHA-256 of
// (question_title + question_helper + locale) wrapped in a synthetic GET
// Request (the Cache API keys on GET URLs). Only CLEAN responses are cached;
// filtered fallbacks are never cached so a later prompt fix is not masked.
//
// Everything here is fail-open: any cache error is swallowed and the request
// proceeds to a live generation. Caching must never break a response.
//
// `caches` is undefined under vitest/node, so cacheAvailable() returns false
// and the whole layer no-ops in tests.
// ---------------------------------------------------------------------------

const CACHE_TTL_SECONDS = 86_400; // 24h

function cacheAvailable(): boolean {
  try {
    return typeof caches !== "undefined" && !!(caches as { default?: Cache }).default;
  } catch {
    return false;
  }
}

async function cacheKeyFor(
  questionTitle: string,
  questionHelper: string | undefined,
  locale: string,
): Promise<Request> {
  const material = `${questionTitle}␀${questionHelper ?? ""}␀${locale}`;
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(material));
  const hex = [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
  return new Request(`https://intake-help-cache.civica.internal/${hex}`);
}

async function tryCacheMatch(key: Request): Promise<HelpResponse | null> {
  try {
    if (!cacheAvailable()) return null;
    const hit = await caches.default.match(key);
    if (!hit) return null;
    return (await hit.json()) as HelpResponse;
  } catch {
    return null;
  }
}

function tryCachePut(c: Context<{ Bindings: Env }>, key: Request, body: HelpResponse): void {
  try {
    if (!cacheAvailable()) return;
    const resp = new Response(JSON.stringify(body), {
      headers: {
        "content-type": "application/json",
        "cache-control": `max-age=${CACHE_TTL_SECONDS}`,
      },
    });
    const put = caches.default.put(key, resp);
    try {
      c.executionCtx.waitUntil(put);
    } catch {
      // No execution context (tests / unusual host) — fire and forget.
      void put;
    }
  } catch {
    // Fail open: never let a cache write break the response.
  }
}

// ---------------------------------------------------------------------------
// POST /v1/intake/help
// ---------------------------------------------------------------------------

app.post(
  "/",
  requireAnonymousId,
  rateLimit("strict"),
  zValidator("json", helpRequestSchema),
  async (c) => {
    const { question_title, question_helper, locale } = c.req.valid("json");

    const apiKey = c.env.ANTHROPIC_API_KEY;
    if (!apiKey) {
      throw new HTTPException(500, { message: "ANTHROPIC_API_KEY is not configured" });
    }

    // Cache check (fail-open). A hit skips the LLM call entirely.
    const cacheKey = await cacheKeyFor(question_title, question_helper, locale).catch(() => null);
    if (cacheKey) {
      const cached = await tryCacheMatch(cacheKey);
      if (cached) {
        return c.json(cached);
      }
    }

    const systemPrompt = locale === "es" ? TIER_B_SYSTEM_PROMPT_ES : TIER_B_SYSTEM_PROMPT_EN;
    const fetchImpl = _fetchOverride ?? fetch;

    let rawText: string;
    try {
      rawText = await callAnthropic(apiKey, systemPrompt, question_title, question_helper, fetchImpl);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Anthropic call failed";
      // Log the failure server-side; surface a 500 so the iOS sheet can show
      // its error state (echo of question_title + navigator nudge per D6).
      console.log(
        JSON.stringify({
          level: "error",
          msg: "intake_help_llm_failure",
          route: "POST /v1/intake/help",
          locale,
          error: message,
          question_title: question_title.slice(0, 200),
          ts: new Date().toISOString(),
        }),
      );
      throw new HTTPException(500, { message: "LLM generation failed" });
    }

    const anonymousId = c.req.header("x-anonymous-id")?.trim() ?? null;
    const filtered = applySafetyFilter(rawText, locale, {
      question_title,
      anonymous_id: anonymousId,
    });

    const body: HelpResponse = {
      explainer_text: filtered.text,
      was_filtered: filtered.was_filtered,
    };

    // Cache only CLEAN responses — never cache a filtered fallback, so a
    // later prompt fix is not masked by a stale safe-fallback.
    if (cacheKey && !filtered.was_filtered) {
      tryCachePut(c, cacheKey, body);
    }

    return c.json(body);
  },
);

export default app;

